node = nuke.thisNode() 
node['licenseCheckTrigger'].execute() 
proceed = bool(node['licenseCheckResult'].getValue()) 
if proceed: 
  p = nuke.Panel('Create Camera Views') 
  numCameras = len(node['rigViews'].value().split(' ')) 
  p.addSingleLineInput('Num Cameras:', numCameras) 
  ret = p.show() 
  if ret: 
    try: 
      numCameras = int(p.value('Num Cameras:')) 
    except ValueError: 
      nuke.message('Invalid camera number') 
      proceed = False 
  else: 
    proceed = False 
if proceed: 
  for v in nuke.views(): 
    if v.startswith('cam'): 
      nuke.deleteView(v) 
  for i in range(numCameras): 
    nuke.addView('cam' + str(i + 1))

